<?php
declare(strict_types=1);

/**
 * Phase 7c (Real Estate) end-to-end test: Real Estate templates 02–10 generated by tools/template-factory.
 *
 *   php tests/phase7c_realestate_test.php <builder-url> <email> <password> <website-ids> <db-dsn> [export-website-id]
 *
 * <website-ids> is a comma-separated list of nine freshly generated websites, one per template, in order
 * realestate_template_02 … realestate_template_10. <db-dsn> is "dsn|user|password" for the builder database.
 */

require __DIR__ . '/support.php';

/** The enquiry form on a listing page: token, back-slug and absolute action URL. */
function enquiryForm(Client $site, string $host, string $path): array
{
    $html = $site->req('GET', $path, [], false)['body'];
    preg_match('/<form class="wblist-form" method="post" action="([^"]*\/form\/enquiry)"/', $html, $act);
    preg_match('/name="_t" value="([^"]+)"/', $html, $t);
    preg_match('/name="_back" value="([^"]*)"/', $html, $b);
    return ['html' => $html, 'action' => isset($act[1]) ? $host . html_entity_decode($act[1]) : '', 't' => $t[1] ?? '', 'back' => $b[1] ?? ''];
}

[$_, $base, $email, $password, $ids, $dsn, $exportId] = $argv + [null, 'http://127.0.0.1:8080', 'info@channelsoftech.com', '', '', '', '0'];
$base = rtrim((string) $base, '/');
