$sfx = substr(bin2hex(random_bytes(3)), 0, 6);
$pass = $fail = 0;
$started = microtime(true);
$root = dirname(__DIR__);

// Expected design per template: prefix, hero/header/footer variants and a phrase from the demo copy.
$expect = [
    '02' => ['cvl', 'cover', 'center', 'columns', 'photo', 'tiles', 'Your own villa by the Goan coast'],
    '03' => ['nvk', 'panel', 'dark', 'columns', 'classic', 'cards', 'Homes built to last, by Navkar'],
    '04' => ['mrs', 'editorial', 'pill', 'centered', 'classic', 'tiles', 'Workspace that works as hard as you do'],
    '05' => ['bhl', 'split', 'bar', 'band', 'photo', 'cards', 'Build your home on land you can trust'],
    '06' => ['hhv', 'stack', 'pill', 'centered', 'classic', 'tiles', 'Rent a home you’ll love coming back to'],
    '07' => ['bwr', 'split', 'center', 'centered', 'photo', 'cards', 'Come home to the backwaters'],
    '08' => ['gft', 'cover', 'dark', 'columns', 'classic', 'tiles', 'A whole neighbourhood, ready for you'],
    '09' => ['hcr', 'panel', 'bar', 'band', 'photo', 'cards', 'Weekends in the hills, every weekend'],
    '10' => ['hhr', 'editorial', 'center', 'band', 'classic', 'tiles', 'Homes with history, and room for yours'],
];
$known = ['mrd', 'kst', 'hzt', 'sfr', 'lvh', 'skl', 'ldg', 'crl', 'lyc', 'trm', 'nbf', 'vtx', 'gfh', 'icw', 'bpt', 'scr', 'cmc', 'hbc', 'pls', 'lac', 'apx', 'mit', 'cis', 'cfa', 'rsp', 'wsm', 'lgb', 'pcr', 'srh', 'scd', 'cse', 'lhc', 'psd', 'rvp', 'vga', 'mnw', 'chi', 'kth', 'vlt', 'gbo', 'dwp', 'aur', 'ttt', 'erc', 'stz', 'ppl'];

[$d, $du, $dp] = explode('|', (string) $dsn) + ['', '', ''];
$pdo = new PDO($d, $du, $dp, [PDO::ATTR_ERRMODE => PDO::ERRMODE_EXCEPTION, PDO::ATTR_DEFAULT_FETCH_MODE => PDO::FETCH_ASSOC]);

echo "\n== Template files ==\n";
$prefixes = [];
$descriptions = [];
$designs = [];
foreach ($expect as $n => [$p, $hero, $header, $footer, $card, $cats]) {
    $dir = "$root/templates/real-estate/realestate_template_$n";
    $m = json_decode((string) @file_get_contents("$dir/manifest.json"), true) ?: [];
    $css = (string) @file_get_contents("$dir/assets/css/style.css");
    $layout = (string) @file_get_contents("$dir/layouts/default.php");
    $prefixes[] = $p;
    $descriptions[] = $m['description'] ?? '';
    $designs[] = "$hero/$header/$footer/$card/$cats/" . ($m['theme']['defaults']['heading_font'] ?? '') . '/' . ($m['theme']['defaults']['primary'] ?? '');

    $files = new RecursiveIteratorIterator(new RecursiveDirectoryIterator($dir, FilesystemIterator::SKIP_DOTS));
    $leftover = [];
    $foreign = [];
    foreach ($files as $f) {
        if (!preg_match('/\.(php|css|js|json)$/', $f->getFilename())) {
            continue;
        }
        $txt = (string) file_get_contents($f->getPathname());
        if (str_contains($txt, '{{')) {
            $leftover[] = $f->getFilename();
        }
        foreach ($known as $k) {
            if (preg_match('/(?<![a-z-])' . $k . '-[a-z]/', $txt)) {
                $foreign[] = $f->getFilename() . ":$k";
            }
        }
    }
    check("$n manifest: id, name, category, version, unique description", ($m['id'] ?? '') === "realestate_template_$n" && ($m['category'] ?? '') === 'real-estate' && preg_match('/^\d+\.\d+\.\d+$/', (string) ($m['version'] ?? '')) === 1 && strlen((string) ($m['description'] ?? '')) > 80);
    check("$n uses its own prefix \"$p\" throughout; no placeholders or other templates' classes left", str_contains($layout, "<body class=\"$p ") && !$leftover && !$foreign && preg_match_all("/\\.$p-[a-z]/", $css) > 200, json_encode([$leftover, $foreign]));
    check("$n stylesheet is theme-driven (no hard-coded brand colours)", !str_contains(strtoupper($css), strtoupper((string) ($m['theme']['defaults']['primary'] ?? '#'))) && !str_contains(strtoupper($css), strtoupper((string) ($m['theme']['defaults']['secondary'] ?? '#'))) && str_contains($css, 'var(--wb-primary)'));
    $demo = json_decode((string) @file_get_contents("$dir/demo.json"), true) ?: [];
    preg_match_all('#theme:images/([a-z0-9._-]+)#', json_encode($demo, JSON_UNESCAPED_SLASHES), $im);
    $missing = array_filter(array_unique($im[1]), static fn ($f) => !is_file("$dir/assets/images/$f"));
    $items = $demo['listings']['items'] ?? [];
    $noImg = array_filter($items, static fn ($it) => !is_file("$dir/assets/images/prop-{$it['slug']}.svg") || count($it['gallery'] ?? []) < 3);
    check("$n demo images all exist (" . count(array_unique($im[1])) . " referenced), an exterior and a gallery for every listing, preview.jpg present", !$missing && !$noImg && is_file("$dir/assets/images/hero.svg") && is_file("$dir/assets/images/cta.svg") && is_file("$dir/preview.jpg"), json_encode([array_values($missing), array_column($noImg, 'slug')]));
    $lc = $m['listings'] ?? [];
    $closed = array_filter($items, static fn ($it) => ($it['status'] ?? '') === 'closed');
    $featured = array_filter($items, static fn ($it) => !empty($it['featured']));
    $badAttr = [];
    $keys = array_column($lc['attributes'] ?? [], null, 'key');
    foreach ($items as $it) {
        foreach ($it['attributes'] as $k => $v) {
            if (!isset($keys[$k]) || ($keys[$k]['type'] === 'select' && !in_array($v, $keys[$k]['options'], true)) || ($keys[$k]['type'] === 'number' && !is_int($v))) {
                $badAttr[] = "{$it['slug']}.$k";
            }
        }
    }
    check("$n listings module: valid path, attributes and enquiry; 4 categories, 7–8 listings (6 featured, 1 closed), paise prices, every value matches its attribute", in_array($lc['path'] ?? '', ['properties', 'projects', 'listings'], true) && count($lc['attributes'] ?? []) <= 20 && isset($lc['enquiry']['date_label'], $lc['enquiry']['select_options'])
        && count($demo['listings']['categories'] ?? []) === 4 && count($items) >= 7 && count($featured) === 6 && count($closed) === 1 && !array_filter($items, static fn ($it) => !is_int($it['price']) || $it['price'] < 1000000) && !$badAttr
        && stripos(json_encode($lc['enquiry']), 'date') !== false && !preg_grep('/date/i', [$lc['enquiry']['select_label']]), json_encode($badAttr));
    check("$n has its \"$card\" listing card and \"$cats\" category views, and the hero search partial", is_file("$dir/partials/listing-card.php") && str_contains((string) file_get_contents("$dir/partials/listing-card.php"), "$p-listing-$card") && str_contains((string) file_get_contents("$dir/sections/listing_categories.php"), "$p-ltypes-$cats") && is_file("$dir/partials/listing-search.php") && str_contains((string) file_get_contents("$dir/sections/hero.php"), "partial('listing-search'"));
    $pt = $m['page_types'] ?? [];
    $homeTypes = array_column($demo['pages']['']['sections'] ?? [], 'type');
    check("$n home page type matches its demo; all section types have a view", ($pt['home']['default_sections'] ?? null) === $homeTypes && !array_filter($m['section_types'] ?? [], static fn ($t) => !is_file("$dir/sections/$t.php")));
}
check('Nine distinct prefixes, none shared with existing templates', count(array_unique($prefixes)) === 9 && !array_intersect($prefixes, $known));
check('Nine distinct descriptions and design combinations', count(array_unique($descriptions)) === 9 && count(array_unique($designs)) === 9);

$b = new Client($base);
check('Builder login', ($b->login($email, $password)['json']['ok'] ?? false) === true);
$rows = $pdo->query("SELECT t.code, t.status, c.slug FROM wb_templates t JOIN wb_categories c ON c.id = t.category_id WHERE t.code LIKE 'realestate_template_%'")->fetchAll();
$byCode = array_column($rows, null, 'code');
$okReg = true;
foreach (array_keys($expect) as $n) {
    $okReg = $okReg && ($byCode["realestate_template_$n"]['status'] ?? '') === 'active' && ($byCode["realestate_template_$n"]['slug'] ?? '') === 'real-estate';
}
check('All nine registered and active in the Real Estate category', $okReg, json_encode($byCode));
spl_autoload_register(static function (string $class) use ($root): void {
    if (str_starts_with($class, 'App\\') && is_file($f = $root . '/app/' . str_replace('\\', '/', substr($class, 4)) . '.php')) {
        require $f;
    } elseif (str_starts_with($class, 'SiteRuntime\\') && is_file($f = $root . '/runtime/core/' . str_replace('\\', '/', substr($class, 12)) . '.php')) {
        require $f;
    }
});
$cats = $pdo->query('SELECT slug FROM wb_categories')->fetchAll(PDO::FETCH_COLUMN);
$report = [];
foreach (array_keys($expect) as $n) {
    $v = (new App\Modules\Templates\ManifestValidator())->validate("$root/templates/real-estate/realestate_template_$n", $cats, "realestate_template_$n", 'real-estate');
    if ($v->errors() || $v->warnings()) {
        $report[$n] = [$v->errors(), $v->warnings()];
    }
}
check('Template validator: no errors or warnings for any of the nine', !$report, json_encode($report));

preg_match('/font-monospace" value="([A-Za-z0-9]+)"/', $b->req('GET', 'settings', [], false)['body'], $mm);
$qa = 'qa:' . ($mm[1] ?? '');

echo "\n== Generated sites ==\n";
$n = 2;
foreach ($ids as $wid) {
    $key = sprintf('%02d', $n++);
    [$p, $hero, $header, $footer, $card, $cats, $phrase] = $expect[$key];
    $tdir = "$root/templates/real-estate/realestate_template_$key";
    $demo = json_decode((string) file_get_contents("$tdir/demo.json"), true);
    $lc = json_decode((string) file_get_contents("$tdir/manifest.json"), true)['listings'];
    $path = $lc['path'];
    $items = $demo['listings']['items'];
    $tp = (string) $pdo->query('SELECT table_prefix FROM wb_websites WHERE id = ' . $wid)->fetchColumn();
    $pdo->exec("DELETE FROM {$tp}login_attempts WHERE ip IN ('127.0.0.1', '::1')");
    $pdo->exec("UPDATE {$tp}contact_submissions SET created_at = created_at - INTERVAL 2 HOUR WHERE ip IN ('127.0.0.1', '::1')");
    $owner = "re{$key}owner$sfx@example.com";
    $r = $b->req('POST', "websites/$wid/admin-account", ['email' => $owner, 'name' => 'Owner']);
    $siteUrl = substr(rtrim((string) ($r['json']['url'] ?? ''), '/'), 0, -strlen('admin'));
    $host = (string) preg_replace('#^(https?://[^/]+).*$#', '$1', $siteUrl);
    $pub = new Client($siteUrl);
    $pub->basic = $qa;

    $counts = [(int) $pdo->query("SELECT COUNT(*) FROM {$tp}listings")->fetchColumn(), (int) $pdo->query("SELECT COUNT(*) FROM {$tp}listing_categories")->fetchColumn()];
    check("$key demo listings imported: " . count($items) . ' listings, 4 categories', $counts === [count($items), 4], json_encode($counts));

    $home = $pub->req('GET', '', [], false);
    $h = $home['body'];
    check("$key home 200 with body class \"$p\", $header header, $hero hero, $footer footer", $home['code'] === 200 && str_contains($h, "<body class=\"$p $p-mood-") && str_contains($h, "$p-header-$header") && str_contains($h, "$p-hero-$hero") && str_contains($h, "$p-footer-$footer"));
    check("$key hero copy, menu with \"{$lc['menu_label']}\" and its categories, header button, legal links", str_contains($h, htmlspecialchars($phrase, ENT_QUOTES)) && str_contains($h, '>' . htmlspecialchars($lc['menu_label'], ENT_QUOTES) . '</a>') && substr_count($h, "/$path?c=") >= 4
        && substr_count($h, 'class="nav-link') >= 5 && str_contains($h, 'privacy-policy') && str_contains($h, 'disclaimer'));
    $for = array_column($lc['attributes'], null, 'key')['listing_for']['options'] ?? [];
    check("$key hero search posts to /$path with location, type and budget" . (count($for) > 1 ? ' and ' . implode('/', $for) . ' tabs' : ''), preg_match('#<form class="' . $p . '-lsearch" method="get" action="[^"]*/' . $path . '"#', $h) === 1 && str_contains($h, 'name="location"') && str_contains($h, 'name="c"') && str_contains($h, 'name="max"')
        && (count($for) > 1) === str_contains($h, 'name="a[listing_for]"'));
    $open = count(array_filter($items, static fn ($it) => $it['status'] === 'active'));
    check("$key home: 4 $cats categories, 6 featured + 3 new listings in $card cards, stats, services, testimonials, CTA", str_contains($h, "$p-ltypes-$cats") && substr_count($h, "class=\"$p-ltype") >= 4 && substr_count($h, "$p-listing $p-listing-$card") === 9
        && str_contains($h, "$p-stats") && str_contains($h, "$p-quote") && str_contains($h, "$p-cta"));
    $first = $items[0];
    check("$key listing cards show price, tags and facts; link to the listing page", str_contains($h, "$p-listing-tags") && str_contains($h, htmlspecialchars($first['title'], ENT_QUOTES)) && str_contains($h, "/$path/{$first['slug']}\"") && (str_contains($h, "$p-listing-facts") || str_contains($h, "$p-listing-chips")));
    preg_match_all('#src="([^"]+/theme/assets/images/[^"?]+)#', $h, $srcs);
    $bad = 0;
    foreach (array_slice(array_unique($srcs[1]), 0, 6) as $src) {
        $bad += $pub->req('GET', $host . html_entity_decode($src), [], false)['code'] === 200 ? 0 : 1;
    }
    check("$key theme images served", count($srcs[1]) >= 10 && $bad === 0);

    $pagesOk = true;
    foreach (['about' => "$p-about", 'services' => "$p-faq", 'team' => "$p-member", 'contact' => "$p-form", 'privacy-policy' => "$p-rich", 'terms-and-conditions' => "$p-rich", 'disclaimer' => "$p-rich"] as $slug => $marker) {
        $pg = $pub->req('GET', $slug, [], false);
        $pagesOk = $pagesOk && $pg['code'] === 200 && str_contains($pg['body'], $marker) && str_contains($pg['body'], "$p-banner") && str_contains($pg['body'], "$p-crumbs");
    }
    check("$key inner pages: about, services (process + FAQ), team, contact, three legal pages — with banner and breadcrumbs", $pagesOk);
    $nf = $pub->req('GET', 'no-such-page-' . $sfx, [], false);
    check("$key 404 page uses the template", $nf['code'] === 404 && str_contains($nf['body'], "$p-404"));

    $idx = $pub->req('GET', $path, [], false);
    $x = $idx['body'];
    check("$key /$path lists all " . count($items) . " in the template's $card cards, with filters, in the template's look", $idx['code'] === 200 && substr_count($x, "$p-listing $p-listing-$card") === count($items) && str_contains($x, 'wblist-filters') && str_contains($x, "<body class=\"$p ") && str_contains($x, count($items) . ' ' . strtolower($lc['plural']) . ' found'));
    $cat = $demo['listings']['categories'][0]['slug'];
    $inCat = count(array_filter($items, static fn ($it) => $it['category'] === $cat));
    $fc = $pub->req('GET', "$path?c=$cat", [], false)['body'];
    check("$key category filter ($cat) shows its $inCat", substr_count($fc, "$p-listing $p-listing-$card") === $inCat);
    if (count($for) > 1) {
        $o = $for[1];
        $nFor = count(array_filter($items, static fn ($it) => ($it['attributes']['listing_for'] ?? '') === $o));
        $ff = $pub->req('GET', $path . '?' . http_build_query(['a' => ['listing_for' => $o]]), [], false)['body'];
        check("$key \"$o\" filter shows its $nFor", substr_count($ff, "$p-listing $p-listing-$card") === $nFor);
    }
    $closed = array_values(array_filter($items, static fn ($it) => $it['status'] === 'closed'))[0];
    check("$key closed listing marked \"{$lc['closed_label']}\"", str_contains($x, "$p-listing $p-listing-$card $p-card is-closed") || str_contains($x, "$p-listing $p-listing-$card is-closed"));

    $e = enquiryForm($pub, $host, "$path/{$first['slug']}");
    $dp = $e['html'];
    check("$key listing page: title, price, gallery of " . count($first['gallery']) . ' images, specs, enquiry form, similar listings in template cards', str_contains($dp, htmlspecialchars($first['title'], ENT_QUOTES)) && substr_count($dp, 'wblist-gallery-item') >= 3 && str_contains($dp, 'wblist-specs')
        && str_contains($dp, htmlspecialchars($lc['enquiry']['heading'], ENT_QUOTES)) && str_contains($dp, "$p-listing $p-listing-$card") && $e['action'] !== '');
    sleep(3);
    $date = date('Y-m-d', strtotime('+5 days'));
    $extra = [$lc['singular'] => $first['title'], $lc['enquiry']['select_label'] => $lc['enquiry']['select_options'][0], $lc['enquiry']['date_label'] => $date];
    $r = $pub->req('POST', $e['action'], ['_t' => $e['t'], '_back' => $e['back'], 'name' => "Buyer $key $sfx", 'phone' => '+91 98450 33333', 'email' => '', 'message' => 'Please call', 'extra' => $extra], false);
    $row = $pdo->query("SELECT form_key, extra_json FROM {$tp}contact_submissions WHERE name = " . $pdo->quote("Buyer $key $sfx"))->fetch();
    check("$key enquiry with " . strtolower($lc['enquiry']['select_label']) . ' and date stored against the listing; thank-you shown', $r['code'] === 303 && str_contains($r['location'], 'status=sent') && $row && $row['form_key'] === 'enquiry' && json_decode($row['extra_json'], true) === $extra
        && str_contains($pub->req('GET', $r['location'], [], false)['body'], htmlspecialchars($lc['enquiry']['success'], ENT_QUOTES)), json_encode($row));

    $html = $pub->req('GET', 'contact', [], false)['body'];
    preg_match('/<form class="' . $p . '-form" method="post" action="([^"]*\/form\/contact)"/', $html, $act);
    preg_match('/name="_t" value="([^"]+)"/', $html, $t);
    preg_match('/name="_back" value="([^"]*)"/', $html, $bk);
    $pdo->exec("UPDATE {$tp}contact_submissions SET created_at = created_at - INTERVAL 2 HOUR WHERE ip IN ('127.0.0.1', '::1')");
    sleep(3);
    $post = $pub->req('POST', $host . html_entity_decode($act[1] ?? ''), ['_t' => $t[1] ?? '', '_back' => $bk[1] ?? '', 'name' => "Client $key $sfx", 'email' => "c$key$sfx@example.com", 'phone' => '+91 98450 22222', 'subject' => 'Enquiry', 'message' => "Question about template $key."], false);
    $after = $pub->req('GET', (string) $post['location'], [], false)['body'];
    $saved = (int) $pdo->query("SELECT COUNT(*) FROM {$tp}contact_submissions WHERE name = " . $pdo->quote("Client $key $sfx"))->fetchColumn();
    check("$key contact form submits, shows the success message and stores the enquiry", isset($act[1]) && str_contains($after, "$p-form-alert is-sent") && $saved === 1);
}
check('Nine websites tested', count($ids) === 9);

if ((int) $exportId > 0) {
    echo "\n== Export ==\n";
    $r = $b->req('POST', "websites/$exportId/exports", ['type' => 'full', 'prefix' => 'site_']);
    $eid = $r['json']['state']['export_id'] ?? 0;
    $st = ['status' => 'running'];
    for ($i = 0; $i < 20 && ($st['status'] ?? '') === 'running'; $i++) {
        $st = $b->req('POST', "websites/$exportId/exports/$eid/step")['json']['state'] ?? ['status' => 'error'];
    }
    check('Full export of a factory-built site completes', ($st['status'] ?? '') === 'done', json_encode($st));
    $zip = $b->req('GET', "websites/$exportId/exports/$eid/download", [], false);
    $tmp = tempnam(sys_get_temp_dir(), 'z7r');
    file_put_contents($tmp, $zip['body']);
    $za = new ZipArchive();
    $names = [];
    if ($za->open($tmp) === true) {
        for ($i = 0; $i < $za->numFiles; $i++) {
            $names[] = $za->getNameIndex($i);
        }
        $za->close();
    }
    unlink($tmp);
    $flat = implode("\n", $names);
    check('Export contains the template (layout, stylesheet, listing images, listing partials)', str_contains($flat, 'layouts/default.php') && str_contains($flat, 'assets/css/style.css') && str_contains($flat, 'assets/images/hero.svg') && preg_match('#assets/images/prop-[a-z0-9-]+\\.svg#', $flat) === 1 && str_contains($flat, 'partials/listing-card.php') && str_contains($flat, 'partials/listing-search.php'));
    check('Export contains no factory tooling', !str_contains($flat, 'template-factory') && !preg_match('/\.py$/m', $flat));
}

printf("\n%d passed, %d failed (%.1fs)\n", $pass, $fail, microtime(true) - $started);
exit($fail ? 1 : 0);
